#include <bits/stdc++.h>
using namespace std;

int const Mxn = 2e5 + 2;
long long int const MOD = 1e9 + 7;

vector<vector<array<int, 2>>> adj;
vector<array<int, 3>> Edges;
long long int precalc[Mxn];


struct DSU {
  vector<int> leader;
  vector<int> sz;
  int components;

  DSU(int N) {
    leader.resize(N); iota(leader.begin(), leader.end(), 0);
    sz.assign(N, 1);
    components = N;
  }

  int find(int x) {
    return (leader[x] == x) ? x : (leader[x] = find(leader[x]));
  }

  void unite(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return;
    if (sz[x] < sz[y]) swap(x, y);
    leader[y] = leader[x]; sz[x] += sz[y];
    components--;
  }
};

bool valid = 1;
int pref[Mxn];

void dfs(int node = 0) {
  for (auto [child, w] : adj[node]) {
    if (pref[child] == -1) {
      pref[child] = pref[node]^w;
      dfs(child);
    } else {
      if ((pref[child]^pref[node]) != w) valid = 0;
    }
  }
}

int main() {
  precalc[0] = 1;
  for (int i = 1; i < Mxn; i++) {
    precalc[i] = (precalc[i - 1]<<30)%MOD;
  }

  int tt; 
  for (cin >> tt; tt; --tt) {

    int N, M, K, Q;
    cin >> N >> M >> K >> Q;

    Edges.clear();
    adj.clear();
    adj.assign(N + M, vector<array<int, 2>>{});

    DSU dsu(N + M);
    dsu.components = N + M;

    int x, y, z;
    for (int i = 0; i < K; i++) {
      cin >> x >> y >> z;
      x--, y--;
      adj[x].push_back({y + N, z});
      adj[y + N].push_back({x, z});
      dsu.unite(x, y + N);
    }

    for (int i = 0; i < Q; i++) {
      cin >> x >> y >> z;
      x--, y--;
      Edges.push_back({x, y + N, z});
    }

    int firstzero = 0;

    for (int k = 20; k >= 0; k--) {
      if (firstzero + (1<<k) > Q) continue;

      for (int i = firstzero; i < firstzero + (1<<k); i++) {
        x = Edges[i][0], y = Edges[i][1], z = Edges[i][2];
        adj[x].push_back({y, z});
        adj[y].push_back({x, z});
      }

      valid = 1;
      for (int i = 0; i < N + M; i++) pref[i] = -1;
      for (int i = 0; i < N + M; i++) {
        if (pref[i] == -1) pref[i] = 0, dfs(i);
      }

      if (!valid) {
        for (int i = firstzero + (1<<k) - 1; i >= firstzero; --i) {
          x = Edges[i][0], y = Edges[i][1];
          adj[x].pop_back();
          adj[y].pop_back();
        }
      } else {
        firstzero += (1<<k);
      }
    }

    if (firstzero == 0) {
      valid = 1;
      for (int i = 0; i < N + M; i++) pref[i] = -1;
      for (int i = 0; i < N + M; i++) {
        if (pref[i] == -1) pref[i] = 0, dfs(i);
      }

      if (!valid) firstzero--;
    }

    for (int i = 0; i <= Q; i++) {
      if (i <= firstzero) cout << precalc[dsu.components - 1] << '\n';
      else cout << 0 << '\n';
      if (i == Q) break;
      x = Edges[i][0], y = Edges[i][1];
      dsu.unite(x, y);
    }

  }
}
